1	import { afterEach, beforeEach, describe, expect, it } from "vitest";
2	import { storeOAuthState, validateOAuthState } from "@/utils/oauth";
3	
4	describe("oauth state", () => {
5	  beforeEach(() => {
6	    sessionStorage.clear();
7	  });
8	
9	  afterEach(() => {
10	    sessionStorage.clear();
11	  });
12	
13	  it("round-trips the linking user for link flows", async () => {
14	    const { state } = await storeOAuthState("identity-providers/google", "link", "/settings", "users/alice");
15	
16	    expect(validateOAuthState(state)).toEqual({
17	      identityProviderName: "identity-providers/google",
18	      flowMode: "link",
19	      returnUrl: "/settings",
20	      linkingUserName: "users/alice",
21	      codeVerifier: expect.any(String),
22	    });
23	  });
24	
25	  it("defaults older states to signin without a linking user", () => {
26	    sessionStorage.setItem(
27	      "oauth_state",
28	      JSON.stringify({
29	        state: "legacy-state",
30	        identityProviderName: "identity-providers/google",
31	        timestamp: Date.now(),
32	        returnUrl: "/auth",
33	      }),
34	    );
35	
36	    expect(validateOAuthState("legacy-state")).toEqual({
37	      identityProviderName: "identity-providers/google",
38	      flowMode: "signin",
39	      returnUrl: "/auth",
40	      linkingUserName: undefined,
41	      codeVerifier: undefined,
42	    });
43	  });
44	});
