1	import { useQuery } from "@tanstack/react-query";
2	import { identityProviderServiceClient } from "@/connect";
3	import { IdentityProvider } from "@/types/proto/api/v1/idp_service_pb";
4	
5	// Query keys factory
6	export const identityProviderKeys = {
7	  all: ["identityProviders"] as const,
8	  list: () => [...identityProviderKeys.all, "list"] as const,
9	};
10	
11	const EMPTY_LIST: IdentityProvider[] = [];
12	
13	// Hook to fetch the configured identity providers. Pass `enabled: false` on
14	// pages/branches that never render provider buttons to skip the request.
15	export function useIdentityProviderList(enabled = true) {
16	  const { data, isLoading } = useQuery({
17	    queryKey: identityProviderKeys.list(),
18	    queryFn: async () => (await identityProviderServiceClient.listIdentityProviders({})).identityProviders,
19	    staleTime: 60_000,
20	    enabled,
21	  });
22	  return {
23	    identityProviderList: data ?? EMPTY_LIST,
24	    isLoading,
25	  };
26	}
